<script setup lang="ts">
import type { FinanceStudentAccountStatement, FinanceStudentAccountSummary } from '@emhare/portal-shell/types/finance'

definePageMeta({ layout: 'dashboard' })
const api=useEmhareApi();const { showError }=useEmhareConfirm();const accounts=ref<FinanceStudentAccountSummary[]>([]);const statement=ref<FinanceStudentAccountStatement|null>(null);const loading=ref(false);const statementLoading=ref(false);const search=ref('');const selectedAccountId=ref<string|null>(null)
const visibleAccounts=computed(()=>{const query=search.value.trim().toLowerCase();return accounts.value.filter(item=>!query||[item.studentNumber,item.accountNumber,item.primaryEmail].some(value=>value.toLowerCase().includes(query)))})
const totals=computed(()=>({debit:accounts.value.filter(item=>item.baseBalance>0).reduce((sum,item)=>sum+item.baseBalance,0),credit:Math.abs(accounts.value.filter(item=>item.baseBalance<0).reduce((sum,item)=>sum+item.baseBalance,0)),debtors:accounts.value.filter(item=>item.baseBalance>0).length,credits:accounts.value.filter(item=>item.baseBalance<0).length}))
onMounted(load)
async function load(){loading.value=true;try{accounts.value=await api.request<FinanceStudentAccountSummary[]>('/api/finance/collections/accounts');if(selectedAccountId.value)await selectAccount(selectedAccountId.value)}catch(error){await showError('Student account register could not be loaded',api.errorMessage(error))}finally{loading.value=false}}
async function selectAccount(id:string){selectedAccountId.value=id;statementLoading.value=true;try{statement.value=await api.request<FinanceStudentAccountStatement>(`/api/finance/collections/accounts/${id}/statement`)}catch(error){await showError('Student account statement could not be loaded',api.errorMessage(error))}finally{statementLoading.value=false}}
function money(value:number,currency='USD'){return new Intl.NumberFormat('en-ZW',{style:'currency',currency}).format(value)}
function date(value:string){return new Intl.DateTimeFormat('en-ZW',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
function lineLabel(value:string){return value.toLowerCase().split('_').map(word=>word.charAt(0).toUpperCase()+word.slice(1)).join(' ')}
</script>

<template><UDashboardPanel><template #header><UDashboardNavbar title="Student account inquiry"><template #leading><UDashboardSidebarCollapse /></template><template #right><UButton label="Refresh" icon="i-lucide-refresh-cw" color="neutral" variant="outline" :loading="loading" @click="load" /></template></UDashboardNavbar></template><template #body><div class="space-y-5 p-4 sm:p-6">
  <UAlert color="primary" variant="soft" icon="i-lucide-notebook-tabs" title="One chronological USD subledger" description="Invoices debit the student account. Reconciled payments and posted credit notes credit it. Payment reversals restore the debit. Allocations settle open items without changing the account total." />
  <section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><UCard :ui="{body:'p-4'}"><p class="text-xs uppercase text-muted">Active accounts</p><p class="mt-2 text-2xl font-semibold">{{ accounts.length }}</p></UCard><UCard :ui="{body:'p-4'}"><p class="text-xs uppercase text-muted">Student debtors</p><p class="mt-2 text-2xl font-semibold text-warning">{{ totals.debtors }} · {{ money(totals.debit) }}</p></UCard><UCard :ui="{body:'p-4'}"><p class="text-xs uppercase text-muted">Student credits</p><p class="mt-2 text-2xl font-semibold text-success">{{ totals.credits }} · {{ money(totals.credit) }}</p></UCard><UCard :ui="{body:'p-4'}"><p class="text-xs uppercase text-muted">Base currency</p><p class="mt-2 text-2xl font-semibold text-primary">USD</p></UCard></section>
  <div class="grid gap-5 xl:grid-cols-[360px_minmax(0,1fr)]"><UCard :ui="{body:'p-0'}"><div class="space-y-3 border-b border-muted p-4"><div><p class="text-xs uppercase text-primary">Account register</p><h2 class="mt-1 text-lg font-semibold">Students</h2></div><UInput v-model="search" icon="i-lucide-search" placeholder="Student, account, or email" /></div><EmharePaginatedCollection v-slot="{ items: paginatedAccounts }" :items="visibleAccounts"><div class="max-h-[680px] divide-y divide-muted overflow-y-auto"><button v-for="account in paginatedAccounts" :key="account.id" type="button" class="w-full p-4 text-left transition hover:bg-muted/30" :class="selectedAccountId===account.id?'bg-primary/5':''" @click="selectAccount(account.id)"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><p class="font-medium">{{ account.studentNumber }}</p><p class="mt-1 font-mono text-xs text-primary">{{ account.accountNumber }}</p><p class="mt-1 truncate text-xs text-muted">{{ account.primaryEmail }}</p></div><div class="text-right"><p class="font-semibold" :class="account.baseBalance>0?'text-warning':account.baseBalance<0?'text-success':''">{{ money(account.baseBalance) }}</p><p class="mt-1 text-xs text-muted">{{ account.baseBalance>0?'Due':account.baseBalance<0?'Credit':'Settled' }}</p></div></div></button><p v-if="!visibleAccounts.length" class="p-6 text-center text-sm text-muted">No student finance accounts match.</p></div></EmharePaginatedCollection></UCard>
  <UCard :ui="{body:'p-0'}"><template v-if="statement"><div class="flex flex-wrap items-start justify-between gap-4 border-b border-muted p-4"><div><p class="text-xs uppercase text-primary">Official account inquiry</p><h2 class="mt-1 text-lg font-semibold">{{ statement.account.studentNumber }} · {{ statement.account.accountNumber }}</h2><p class="mt-1 text-sm text-muted">{{ statement.account.primaryEmail }}</p></div><div class="text-right"><p class="text-xs uppercase text-muted">USD balance</p><p class="mt-1 text-2xl font-semibold" :class="statement.account.baseBalance>0?'text-warning':statement.account.baseBalance<0?'text-success':''">{{ money(statement.account.baseBalance) }}</p><p class="text-xs text-muted">{{ statement.account.baseBalance>0?'Amount due':statement.account.baseBalance<0?'Student credit':'Settled' }}</p></div></div><EmharePaginatedCollection v-slot="{ items: paginatedStatementLines }" :items="statement.lines"><div class="overflow-x-auto"><table class="w-full min-w-[980px] text-left text-sm"><thead class="bg-muted/40 text-xs uppercase text-muted"><tr><th class="px-4 py-3">Date and reference</th><th class="px-4 py-3">Entry</th><th class="px-4 py-3 text-right">Transaction debit</th><th class="px-4 py-3 text-right">Transaction credit</th><th class="px-4 py-3 text-right">USD debit</th><th class="px-4 py-3 text-right">USD credit</th><th class="px-4 py-3 text-right">USD balance</th></tr></thead><tbody><tr v-for="line in paginatedStatementLines" :key="`${line.lineType}-${line.reference}`" class="border-t border-muted"><td class="px-4 py-3"><p>{{ date(line.occurredAt) }}</p><p class="mt-1 font-mono text-xs text-primary">{{ line.reference }}</p></td><td class="px-4 py-3"><UBadge :label="lineLabel(line.lineType)" :color="line.lineType==='PAYMENT_REVERSAL'?'error':line.lineType==='PAYMENT'||line.lineType==='CREDIT_NOTE'?'success':'neutral'" variant="subtle" /><p class="mt-1 text-xs text-muted">{{ line.description }}</p></td><td class="px-4 py-3 text-right">{{ line.transactionDebit?money(line.transactionDebit,line.transactionCurrencyCode):'—' }}</td><td class="px-4 py-3 text-right">{{ line.transactionCredit?money(line.transactionCredit,line.transactionCurrencyCode):'—' }}</td><td class="px-4 py-3 text-right">{{ line.baseDebit?money(line.baseDebit):'—' }}</td><td class="px-4 py-3 text-right text-success">{{ line.baseCredit?money(line.baseCredit):'—' }}</td><td class="px-4 py-3 text-right font-semibold">{{ money(line.runningBaseBalance) }}</td></tr><tr v-if="!statement.lines.length"><td colspan="7" class="px-4 py-8 text-center text-muted">No posted account entries.</td></tr></tbody></table></div></EmharePaginatedCollection></template><div v-else class="flex min-h-[420px] items-center justify-center p-8 text-center"><div><UIcon name="i-lucide-notebook-tabs" class="mx-auto size-10 text-muted" /><h2 class="mt-3 font-semibold">Select a student account</h2><p class="mt-1 max-w-sm text-sm text-muted">Open the chronological transaction and USD base-currency statement without changing ledger evidence.</p></div></div><USkeleton v-if="statementLoading" class="m-4 h-48" /></UCard></div>
</div></template></UDashboardPanel></template>
